import os
import json
from typing import Dict, Any, Optional

import requests


AZURE_ENDPOINT = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
AZURE_API_KEY = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_API_KEY")
AZURE_MODEL_ID = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_MODEL_ID", "prebuilt-document")
AZURE_API_VERSION = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_API_VERSION", "2024-02-29-preview")


def extract_key_value_pairs(document_url: str) -> Dict[str, Any]:
    if not AZURE_ENDPOINT or not AZURE_API_KEY:
        raise ValueError(
            "Missing Azure Document Intelligence credentials. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_API_KEY."
        )

    analyze_url = (
        f"{AZURE_ENDPOINT.rstrip('/')}/documentintelligence/documentModels/"
        f"{AZURE_MODEL_ID}:analyze?api-version={AZURE_API_VERSION}"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": AZURE_API_KEY,
        "Content-Type": "application/json",
    }
    payload = {"urlSource": document_url}

    start_resp = requests.post(analyze_url, headers=headers, json=payload, timeout=60)
    start_resp.raise_for_status()

    operation_url = start_resp.headers.get("operation-location")
    if not operation_url:
        raise RuntimeError("Azure Document Intelligence did not return an operation-location header.")

    result = _poll_operation(operation_url, AZURE_API_KEY)
    return _normalize_key_value_pairs(result)


def _poll_operation(operation_url: str, api_key: str, timeout_seconds: int = 120) -> Dict[str, Any]:
    headers = {"Ocp-Apim-Subscription-Key": api_key}
    elapsed = 0
    interval = 2

    while elapsed < timeout_seconds:
        resp = requests.get(operation_url, headers=headers, timeout=60)
        resp.raise_for_status()
        data = resp.json()
        status = data.get("status")
        if status in ("succeeded", "failed", "canceled"):
            if status != "succeeded":
                raise RuntimeError(f"Azure Document Intelligence operation did not succeed: {status}")
            return data
        import time

        time.sleep(interval)
        elapsed += interval

    raise TimeoutError("Timed out waiting for Azure Document Intelligence analysis to complete.")


def _normalize_key_value_pairs(result: Dict[str, Any]) -> Dict[str, Any]:
    output: Dict[str, Any] = {}
    analyze_result: Dict[str, Any] = result.get("analyzeResult", {})

    # Prefer extracted key-value pairs when available
    for kv in analyze_result.get("keyValuePairs", []) or []:
        key = _extract_spans_text(kv.get("key"))
        value = _extract_spans_text(kv.get("value"))
        if key:
            output[key] = value

    # Fallback: extract from documents' fields for form-like structured documents
    for doc in analyze_result.get("documents", []) or []:
        fields = doc.get("fields", {}) or {}
        for field_name, field_data in fields.items():
            value = _field_to_value(field_data)
            if field_name and field_name not in output:
                output[field_name] = value

    return output


def _extract_spans_text(item: Optional[Dict[str, Any]]) -> str:
    if not item:
        return ""
    text = item.get("content")
    if text:
        return text.strip()
    return ""


def _field_to_value(field_data: Optional[Dict[str, Any]]) -> Any:
    if not field_data:
        return None

    field_type = field_data.get("type")
    if "valueString" in field_data:
        return field_data.get("valueString")
    if "valueNumber" in field_data:
        return field_data.get("valueNumber")
    if "valueInteger" in field_data:
        return field_data.get("valueInteger")
    if "valueDate" in field_data:
        return field_data.get("valueDate")
    if "valueTime" in field_data:
        return field_data.get("valueTime")
    if "valuePhoneNumber" in field_data:
        return field_data.get("valuePhoneNumber")
    if "valueCurrency" in field_data:
        return field_data.get("valueCurrency")
    if "valueArray" in field_data:
        return [_field_to_value(v) for v in field_data.get("valueArray", [])]
    if "valueObject" in field_data:
        obj = field_data.get("valueObject", {})
        return {k: _field_to_value(v) for k, v in obj.items()}
    if field_type == "selectionMark":
        return field_data.get("valueSelectionMark")
    if "content" in field_data:
        return field_data.get("content")
    return field_data.get("value") if "value" in field_data else None


def extract_key_value_pairs_from_file(file_path: str) -> Dict[str, Any]:
    if not AZURE_ENDPOINT or not AZURE_API_KEY:
        raise ValueError(
            "Missing Azure Document Intelligence credentials. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_API_KEY."
        )

    analyze_url = (
        f"{AZURE_ENDPOINT.rstrip('/')}/documentintelligence/documentModels/"
        f"{AZURE_MODEL_ID}:analyze?api-version={AZURE_API_VERSION}"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": AZURE_API_KEY,
        "Content-Type": "application/octet-stream",
    }

    with open(file_path, "rb") as f:
        start_resp = requests.post(analyze_url, headers=headers, data=f, timeout=60)
    start_resp.raise_for_status()

    operation_url = start_resp.headers.get("operation-location")
    if not operation_url:
        raise RuntimeError("Azure Document Intelligence did not return an operation-location header.")

    result = _poll_operation(operation_url, AZURE_API_KEY)
    return _normalize_key_value_pairs(result)
